OPJ_BOOL read_rle4_bitmap(FILE *IN, OPJ_UINT8 *pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 expected_pixel_count = width * height;
    OPJ_UINT32 written_pixel_count = 0;
    OPJ_UINT8 *current_pixel = pData;

    while (!feof(IN) && written_pixel_count < expected_pixel_count) {
        OPJ_UINT8 byte;
        if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
            continue;
        }

        if (byte == 0x00) {
            // Handle absolute mode
            OPJ_UINT8 count = 0;
            if (fread(&count, sizeof(OPJ_UINT8), 1, IN) != 1) {
                continue;
            }

            for (OPJ_UINT32 i = 0; i < count && written_pixel_count < expected_pixel_count; ++i) {
                OPJ_UINT8 pixel;
                if (fread(&pixel, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    continue;
                }
                *current_pixel++ = pixel;
                written_pixel_count++;
            }
        } else {
            // Handle encoded mode
            OPJ_UINT32 count = byte;
            OPJ_UINT8 value;
            if (fread(&value, sizeof(OPJ_UINT8), 1, IN) != 1) {
                continue;
            }

            for (OPJ_UINT32 i = 0; i < count && written_pixel_count < expected_pixel_count; ++i) {
                *current_pixel++ = value;
                written_pixel_count++;
            }
        }
    }

    if (written_pixel_count != expected_pixel_count) {
        return OPJ_FALSE;
    }

    return OPJ_TRUE;
}

