        if ((byte & 0x0F) != 0x0F) {
            OPJ_UINT32 count = (byte & 0x0F) + 1;
            OPJ_UINT8 value = (byte & 0xF0) >> 4;
            for (OPJ_UINT32 i = 0; i < count; ++i) {
                pData[pixel_count] = value;
                pixel_count++;
                if (pixel_count % (width * 2) == 0) {
                    y++;
                    if (y >= height) {
                        break;
                    }
                    pData += row_size;
                    pixel_count = 0;
                }
            }
        } else {
            OPJ_UINT8 high_nibble = (byte & 0xF0) >> 4;
