OPJ_BOOL read_and_decode_rle4(FILE *IN, OPJ_UINT8 *pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 row, col;
    OPJ_UINT32 num_pixels = width * height;
    OPJ_UINT32 written_pixels = 0;
    OPJ_UINT8 *ptr = pData;
    OPJ_UINT8 byte;
    OPJ_BOOL success = OPJ_TRUE;

    for (row = 0; row < height && success; row++) {
        for (col = 0; col < stride && written_pixels < num_pixels;) {
            if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                success = OPJ_FALSE;
                break;
            }

            if ((byte & 0x80) == 0x00) {
                /* Encoded mode: run-length encoding */
                OPJ_UINT8 run_length = (byte & 0x7F) + 1;
                OPJ_UINT8 run_value = (byte >> 4) & 0x0F;

                for (OPJ_UINT32 i = 0; i < run_length && written_pixels < num_pixels; i++) {
                    *ptr = run_value;
                    ptr++;
                    written_pixels++;
                    col++;
                }
            } else {
                /* Absolute mode: explicit byte value */
                *ptr = byte & 0x0F;
                ptr++;
                written_pixels++;
                col++;
            }
        }

        if (success && written_pixels < num_pixels) {
            success = OPJ_FALSE;
            break;
        }
    }

    if (written_pixels != num_pixels) {
        success = OPJ_FALSE;
    }

    return success;
}

OPJ_BOOL read_rle4_bitmap(FILE *IN, OPJ_UINT8 *pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 i, j;
    OPJ_UINT32 row;
    OPJ_UINT8 *pRow;
    OPJ_UINT8 value;
    OPJ_UINT32 count;
    OPJ_UINT32 pixelCount = 0;
    OPJ_UINT32 expectedPixels = width * height;

    pRow = pData;
    for (row = 0; row < height; ++row) {
        for (i = 0; i < stride; ) {
            if (feof(IN)) {
                fprintf(stderr, "Unexpected end of file.\n");
                return OPJ_FALSE;
            }
            value = fgetc(IN);
            if (value & 0x80) {
                /* Absolute mode: the next byte is the pixel value */
                if (feof(IN)) {
                    fprintf(stderr, "Unexpected end of file.\n");
                    return OPJ_FALSE;
                }
                value = fgetc(IN);
                count = value & 0x0F;
                for (j = 0; j <= count; ++j) {
                    if (pixelCount >= expectedPixels) {
                        fprintf(stderr, "Output buffer overflow.\n");
                        return OPJ_FALSE;
                    }
                    pRow[pixelCount % width] = (pRow[pixelCount % width] & 0xF0) | ((value >> 4) & 0x0F);
                    pixelCount++;
                }
                for (j = 0; j <= count; ++j) {
                    if (pixelCount >= expectedPixels) {
                        fprintf(stderr, "Output buffer overflow.\n");
                        return OPJ_FALSE;
                    }
                    pRow[pixelCount % width] = (pRow[pixelCount % width] & 0x0F) | ((value << 4) & 0xF0);
                    pixelCount++;
                }
                i += 2;
            } else {
                /* Encoded mode: the next byte is the pixel value */
                if (feof(IN)) {
                    fprintf(stderr, "Unexpected end of file.\n");
                    return OPJ_FALSE;
                }
                value = fgetc(IN);
                count = value & 0x1F;
                if (count == 0x1F) {
                    count = 0;
                    if (feof(IN)) {
                        fprintf(stderr, "Unexpected end of file.\n");
                        return OPJ_FALSE;
                    }
                    count = fgetc(IN);
                }
                count++;
                for (j = 0; j < count; ++j) {
                    if (pixelCount >= expectedPixels) {
                        fprintf(stderr, "Output buffer overflow.\n");
                        return OPJ_FALSE;
                    }
                    pRow[pixelCount % width] = (pRow[pixelCount % width] & 0xF0) | ((value >> 4) & 0x0F);
                    pixelCount++;
                }
                for (j = 0; j < count; ++j) {
                    if (pixelCount >= expectedPixels) {
                        fprintf(stderr, "Output buffer overflow.\n");
                        return OPJ_FALSE;
                    }
                    pRow[pixelCount % width] = (pRow[pixelCount % width] & 0x0F) | ((value << 4) & 0xF0);
                    pixelCount++;
                }
                i += 2;
            }
        }
        pRow += stride;
    }
    if (pixelCount != expectedPixels) {
        fprintf(stderr, "Pixel count mismatch: expected %u, got %u.\n", expectedPixels, pixelCount);
        return OPJ_FALSE;
    }
    return OPJ_TRUE;
}

OPJ_BOOL read_rle4_bitmap(FILE *IN, OPJ_UINT8 *pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 expected_pixel_count = width * height;
    OPJ_UINT32 written_pixels = 0;
    OPJ_UINT32 i = 0;
    OPJ_UINT8 *row_start = pData;
    OPJ_UINT8 byte, count;
    int absolute_mode = 0;

    while (!feof(IN) && written_pixels < expected_pixel_count) {
        if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
            return OPJ_FALSE;
        }

        if (absolute_mode) {
            if (byte & 0x80) {
                absolute_mode = 0;
            }
            pData[written_pixels++] = byte;
            continue;
        }

        if (byte == 0x00) {
            absolute_mode = 1;
            if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                return OPJ_FALSE;
            }
            written_pixels += byte;
            continue;
        }

        count = (byte & 0x7F) + 1;
        byte = (byte >> 7) ? 0 : 0xFF;

        for (OPJ_UINT32 j = 0; j < count; ++j) {
            if (written_pixels >= expected_pixel_count) {
                break;
            }
            pData[written_pixels++] = byte;
        }
    }

    if (written_pixels != expected_pixel_count) {
        return OPJ_FALSE;
    }

    return OPJ_TRUE;
}
